    const polishDashboardCredit=()=>{const cards=state.accounts.filter(account=>account.type==='creditCard'),limits=cards.reduce((sum,account)=>sum+Number(account.creditLimit||0),0),balances=cards.reduce((sum,account)=>sum+Number(account.balance||0),0),available=limits-balances,limitsPlausible=Number.isFinite(available)&&Math.abs(available)<1000000000,utilization=limits>0&&limitsPlausible?balances/limits*100:null,scores=(state.creditScores||[]).map((score,index)=>({...score,_index:index})).sort((a,b)=>(b.date||'').localeCompare(a.date||'')||b._index-a._index),latestFor=user=>scores.find(score=>score.person===user.displayName||score.person===user.preferredName),userScores=state.householdUsers.map(user=>({user,score:latestFor(user)}));scoreCard.innerHTML=`<div class="card-head"><div><h2>Household credit health</h2><div class="card-note">Latest manually recorded score for each household member plus current revolving-credit metrics.</div></div><button class="link-btn" id="recordCreditScoreBtn">Record score</button></div><div class="credit-metric-grid">${userScores.map(({user,score})=>`<div class="credit-metric"><span>${user.preferredName||user.displayName} · latest credit score</span><strong>${score?.score||'Not entered'}</strong><small>${score?.date?dateText(score.date)+(score.source?' · '+score.source:''):'Add a monthly score'}</small></div>`).join('')}<div class="credit-metric"><span>Card utilization</span><strong>${utilization===null?'Review limits':utilization.toFixed(1)+'%'}</strong><small>${utilization===null?'One or more card limits appears invalid.':'Across active credit cards'}</small></div><div class="credit-metric"><span>Available revolving credit</span><strong>${limitsPlausible?money(available):'Review limits'}</strong><small>${limitsPlausible?'Credit limits less current balances':'Check the credit-limit values on card records'}</small></div><div class="credit-metric"><span>Recorded payment status</span><strong>${state.payments?.length?'100% logged':'No history'}</strong><small>Based on payments recorded in CoreValley</small></div></div>${scores.length?`<div class="credit-score-history"><strong>Recent score history</strong>${scores.slice(0,5).map(score=>`<span><b>${score.person}</b> ${score.score} <small>${dateText(score.date)}</small></span>`).join('')}</div>`:''}`;$('#recordCreditScoreBtn').onclick=()=>openSimpleData('Record monthly credit score','Enter the score obtained directly by the household. CoreValley does not retrieve credit reports.',`<div class="field"><label>Person</label><select id="scorePerson">${state.householdUsers.map(user=>`<option>${user.displayName}</option>`).join('')}</select></div><div class="field"><label>Date</label><input id="scoreDate" type="date" value="${new Date().toISOString().slice(0,10)}" required></div><div class="field"><label>Credit score</label><input id="scoreValue" type="number" min="300" max="850" required></div><div class="field"><label>Source</label><input id="scoreSource" placeholder="Issuer, bureau, monitoring service"></div>`,()=>{state.creditScores.push({id:'score-'+Date.now(),person:$('#scorePerson').value,date:$('#scoreDate').value,score:Number($('#scoreValue').value),source:$('#scoreSource').value.trim(),recordedAt:new Date().toISOString()});dataProvider.save(state);renderDashboardUpgrade();polishDashboardCredit();showToast('Credit score recorded.')});lucide.createIcons()};document.head.insertAdjacentHTML('beforeend',`<style>
      .actions{grid-template-columns:repeat(4,minmax(0,1fr));align-items:stretch}.dashboard-upgrade-grid{grid-template-columns:repeat(2,minmax(0,1fr));align-items:stretch}.actions>.card,.dashboard-upgrade-grid>.card{height:100%}.dashboard-upgrade-grid .wide{grid-column:auto}.credit-metric-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px;margin-top:14px}.credit-metric{background:var(--wash);border:1px solid var(--line);border-radius:12px;padding:12px}.credit-metric span{display:block;color:var(--muted);font-size:13px;font-weight:700;line-height:1.35}.credit-metric strong{display:block;font:800 20px Manrope;margin:5px 0 3px}.credit-metric small{display:block;color:var(--muted);font-size:12px;line-height:1.35}.credit-score-history{display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin-top:12px;padding-top:12px;border-top:1px solid var(--line);font-size:12px}.credit-score-history>span{background:var(--wash);border-radius:20px;padding:6px 9px}.credit-score-history small{color:var(--muted);margin-left:4px}@media(max-width:1500px){.actions{grid-template-columns:repeat(2,minmax(0,1fr))}.credit-metric-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:760px){.actions,.dashboard-upgrade-grid,.credit-metric-grid{grid-template-columns:1fr}}
    </style>`);
    const readableSetPage=setPage;setPage=function(page){readableSetPage(page);if(page==='Dashboard')polishDashboardCredit();if(page==='Calendar')renderInteractiveCalendar();if(page==='Contracts & Warranties')setTimeout(filterDocuments,0)};$$('#nav button').forEach(b=>b.onclick=()=>setPage(b.dataset.page));
